'use strict';

const {
    test
  } = require('node:test'),
  assert = require('node:assert/strict'),
  Transport = require('../src/api-transport.cjs'),
  Official = require('../src/official-direct.cjs');
function png() {
  const b = new Uint8Array(24);
  b.set([137, 80, 78, 71, 13, 10, 26, 10]);
  new DataView(b.buffer).setUint32(16, 1216);
  new DataView(b.buffer).setUint32(20, 832);
  return b;
}
test('known Rinko v1 preserves native fields using documented JSON endpoint', () => {
  assert.deepEqual(Transport.route('https://nai.rinko.ai/v1'), {
    kind: 'native-json',
    url: 'https://nai.rinko.ai/v1/nai/generate-image'
  });
  for(const url of ['https://nai.rinko.ai/v1','https://nai.rinko.ai/v1/images/generations'])for(const format of ['auto','openai'])assert.deepEqual(Transport.route(url,format,true),{kind:'native-json',url:'https://nai.rinko.ai/v1/nai/generate-image'});
  assert.equal(Transport.route('https://nai.rinko.ai/v1/images/generations').kind,'openai');
  assert.equal(Transport.route('https://nai.rinko.ai/native').url, 'https://nai.rinko.ai/native/ai/generate-image');
  assert.equal(Transport.route('https://api.hamubox.com/v1/novelai').kind, 'native');
  assert.equal(Transport.route('https://example.com/v1').url, 'https://example.com/v1/images/generations');
  assert.throws(() => Transport.route('https://example.com/v1', 'openai', true), /当前 API 接口不支持 NovelAI 原生图生图/);
});
test('Rinko OpenAI extensions preserve NAI seed while general gateways get explicit generation fields', () => {
  const native = Official.staticRequestBody({
    prompt: 'portrait',
    options: {},
    requestedSeed: 0
  });
  const a = Transport.body(native, 'openai', 'https://nai.rinko.ai/v1/images/generations'),
    b = Transport.body(native, 'openai', 'https://example.com/v1/images/generations');
  assert.equal(a.nai.seed, 0);
  assert.equal(a.nai.steps, 28);
  assert.equal(b.seed, 0);
  assert.equal(b.size, '1216x832');
  assert.equal(b.response_format, 'b64_json');
  assert.equal(Transport.body(native, 'native-json', 'https://example.com'), native);
});
test('JSON image seed is never manufactured from requested or echoed parameters', async () => {
  for (const value of [{
    images: [Official.encode(png())],
    job: {
      parameters: {
        seed: 5
      }
    }
  }, {
    data: [{
      b64_json: Official.encode(png())
    }],
    parameters: {
      seed: 5
    }
  }]) {
    const r = await Transport.jsonImage({
      json: async () => value
    });
    assert.equal(r.seed, null);
    assert.deepEqual(r.bytes, png());
  }
  assert.equal((await Transport.jsonImage({
    json: async () => ({
      data: [{
        b64_json: Official.encode(png()),
        seed: 0
      }]
    })
  })).seed, 0);
});
test('actual Rinko request is submitted once with exact seed and preserves returned JSON seed', async () => {
  let calls = 0,
    stored;
  const previous = global.fetch;
  global.fetch = async (url, options) => {
    calls++;
    assert.equal(url, 'https://nai.rinko.ai/v1/nai/generate-image');
    const body = JSON.parse(options.body);
    assert.equal(body.parameters.seed, 42);
    assert.equal(body.action, 'generate');
    return {
      ok: true,
      headers: {
        get: () => null
      },
      json: async () => ({
        images: [Official.encode(png())],
        seed: 42
      })
    };
  };
  try {
    const result = await Official.generate({
      variable: {
        get: async () => ({
          provider: 'thirdparty',
          thirdParty: {
            url: 'https://nai.rinko.ai/v1',
            apiKey: 'test-key'
          }
        })
      },
      file: {
        save: async (n, b) => {
          stored = b;
          return 'files/chat/' + n;
        }
      }
    }, {
      staticDirect: true,
      prompt: 'portrait',
      requestedSeed: 42,
      options: {}
    }, {
      id: 'json'
    }, async () => {});
    assert.equal(calls, 1);
    assert.equal(result.seed, 42);
    assert.equal(result.directAudit.apiFormat, 'native-json');
    assert.deepEqual(Official.decode(stored), png());
  } finally {
    global.fetch = previous;
  }
});
test('remote JSON image links receive no API authorization headers', async () => {
  const previous = global.fetch;
  global.fetch = async (url, options) => {
    assert.equal(url, 'https://cdn.example/image.png');
    assert.equal(options.headers, undefined);
    assert.equal(options.redirect, 'error');
    assert.equal(options.credentials, 'omit');
    return {
      ok: true,
      arrayBuffer: async () => png().buffer
    };
  };
  try {
    assert.deepEqual((await Transport.jsonImage({
      json: async () => ({
        data: [{
          url: 'https://cdn.example/image.png'
        }]
      })
    })).bytes, png());
  } finally {
    global.fetch = previous;
  }
});
